#!/usr/bin/env node
// Inline the bundled .riv files as base64 into a JS module.
//
// WeChat's getFileSystemManager().readFile() cannot reliably read code-package
// files (permission denied on build-tool-copied / subpackage assets), so instead
// of shipping loose .riv files we bundle their bytes as code — always readable,
// no filesystem permissions involved.
//
//   node scripts/inline-riv.mjs   ->  src/pkgRive/assets/riv-data.js

import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const RIV_DIR = join(__dirname, '..', 'src', 'pkgRive', 'assets', 'riv')
const OUT = join(__dirname, '..', 'src', 'pkgRive', 'assets', 'riv-data.js')

const files = readdirSync(RIV_DIR).filter((f) => f.endsWith('.riv')).sort()
const map = {}
let total = 0
for (const f of files) {
  const buf = readFileSync(join(RIV_DIR, f))
  map[f] = buf.toString('base64')
  total += buf.length
}

const body =
  '// AUTO-GENERATED by scripts/inline-riv.mjs — base64 of bundled .riv files.\n' +
  '// Regenerate after changing assets/riv/*.riv: node scripts/inline-riv.mjs\n' +
  'module.exports = ' + JSON.stringify(map) + '\n'

writeFileSync(OUT, body)
console.log(
  `[inline-riv] ${files.length} files (${(total / 1024).toFixed(0)}KB raw) ` +
    `-> riv-data.js (${(body.length / 1024).toFixed(0)}KB base64)`
)
